SET search_path=elite_diary,public;
CREATE TABLE IF NOT EXISTS user_handles(user_id TEXT PRIMARY KEY REFERENCES users(id),username TEXT NOT NULL UNIQUE,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS class_subjects(class_id TEXT NOT NULL REFERENCES academics(id),subject_id TEXT NOT NULL REFERENCES academics(id),PRIMARY KEY(class_id,subject_id));
CREATE TABLE IF NOT EXISTS teacher_reviewers(teacher_id TEXT PRIMARY KEY REFERENCES users(id),head_id TEXT NOT NULL REFERENCES users(id),CHECK(teacher_id<>head_id));
CREATE TABLE IF NOT EXISTS connections(id TEXT PRIMARY KEY,user_low TEXT NOT NULL REFERENCES users(id),user_high TEXT NOT NULL REFERENCES users(id),sender_id TEXT NOT NULL REFERENCES users(id),recipient_id TEXT NOT NULL REFERENCES users(id),state TEXT NOT NULL CHECK(state IN('pending','accepted','rejected','cancelled','removed')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(user_low,user_high),CHECK(user_low<user_high));
CREATE TABLE IF NOT EXISTS user_blocks(user_id TEXT NOT NULL REFERENCES users(id),blocked_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,PRIMARY KEY(user_id,blocked_id),CHECK(user_id<>blocked_id));
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('direct','group')),name TEXT NOT NULL,creator_id TEXT NOT NULL REFERENCES users(id),connection_id TEXT UNIQUE REFERENCES connections(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_members(conversation_id TEXT NOT NULL REFERENCES conversations(id),user_id TEXT NOT NULL REFERENCES users(id),active INTEGER NOT NULL DEFAULT 1,last_read_at TEXT,joined_at TEXT NOT NULL,PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS membership_events(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),user_id TEXT NOT NULL REFERENCES users(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL CHECK(action IN('joined','removed','left')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chat_messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),sender_id TEXT NOT NULL REFERENCES users(id),client_id TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(sender_id,client_id));
CREATE TABLE IF NOT EXISTS communication_reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES users(id),reported_user_id TEXT NOT NULL REFERENCES users(id),conversation_id TEXT REFERENCES conversations(id),reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS connection_recipient ON connections(recipient_id,state);
CREATE INDEX IF NOT EXISTS chat_conversation_time ON chat_messages(conversation_id,created_at,id);
CREATE INDEX IF NOT EXISTS members_user ON conversation_members(user_id,active);
INSERT INTO user_handles SELECT id,'u_' || replace(id,'-',''),created_at FROM users ON CONFLICT DO NOTHING;
INSERT INTO class_subjects SELECT DISTINCT s.parent_id,a.subject_id FROM assignments a JOIN academics s ON s.id=a.section_id WHERE s.parent_id IS NOT NULL ON CONFLICT DO NOTHING;
INSERT INTO teacher_reviewers SELECT teacher_id,MIN(head_id) FROM assignments WHERE active=1 AND NOT EXISTS(SELECT 1 FROM migrations WHERE version=3) GROUP BY teacher_id HAVING COUNT(DISTINCT head_id)=1 ON CONFLICT DO NOTHING;
ALTER TABLE elite_diary.user_handles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.user_handles FROM PUBLIC,anon,authenticated;
ALTER TABLE elite_diary.class_subjects ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.class_subjects FROM PUBLIC,anon,authenticated;
ALTER TABLE elite_diary.teacher_reviewers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.teacher_reviewers FROM PUBLIC,anon,authenticated;
ALTER TABLE elite_diary.connections ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.connections FROM PUBLIC,anon,authenticated;
ALTER TABLE elite_diary.user_blocks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.user_blocks FROM PUBLIC,anon,authenticated;
ALTER TABLE elite_diary.conversations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.conversations FROM PUBLIC,anon,authenticated;
ALTER TABLE elite_diary.conversation_members ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.conversation_members FROM PUBLIC,anon,authenticated;
ALTER TABLE elite_diary.membership_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.membership_events FROM PUBLIC,anon,authenticated;
ALTER TABLE elite_diary.chat_messages ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.chat_messages FROM PUBLIC,anon,authenticated;
ALTER TABLE elite_diary.communication_reports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON elite_diary.communication_reports FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS immutable_history ON elite_diary.membership_events;
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON elite_diary.membership_events FOR EACH ROW EXECUTE FUNCTION elite_diary.prevent_history_mutation();
DROP TRIGGER IF EXISTS immutable_history ON elite_diary.chat_messages;
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON elite_diary.chat_messages FOR EACH ROW EXECUTE FUNCTION elite_diary.prevent_history_mutation();
DROP TRIGGER IF EXISTS immutable_history ON elite_diary.communication_reports;
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON elite_diary.communication_reports FOR EACH ROW EXECUTE FUNCTION elite_diary.prevent_history_mutation();
INSERT INTO elite_diary.migrations VALUES(3,to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ON CONFLICT DO NOTHING;
RESET search_path;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='elite_diary_app') THEN
